import { Outlet } from 'react-router-dom'
import { useIdentity } from '@/app/providers/IdentityProvider'
import { useAuth } from '@/app/providers/AuthProvider'
import { useTenant } from '@/app/providers/TenantProvider'

/**
 * Renders identity/access empty states. Mount inside <AuthGuard> so the user
 * is guaranteed authenticated when this runs.
 */
export function TenantAccessGuard() {
  const { status, error } = useIdentity()
  const { signOut } = useAuth()
  const { manifest } = useTenant()

  if (status === 'loading') {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-background gap-3">
        <div className="animate-spin rounded-full h-8 w-8 border-2 border-accent border-t-transparent" />
        <p className="text-sm text-muted-foreground">Loading…</p>
      </div>
    )
  }

  if (
    status === 'no_central_user' ||
    status === 'no_tenant_access' ||
    status === 'admin_without_membership'
  ) {
    const title =
      status === 'no_central_user'
        ? 'Account setup required'
        : status === 'admin_without_membership'
        ? 'Tenant membership missing'
        : 'No workspace access'

    const body =
      status === 'no_central_user'
        ? 'Your sign-in succeeded, but no profile row exists yet. An admin must run the bootstrap SQL to provision your account.'
        : status === 'admin_without_membership'
        ? `You have a super_admin role, but no active membership in ${manifest?.name ?? 'this tenant'}. Run supabase/sql/bootstrap_super_admin.sql.`
        : `You don't have access to ${manifest?.name ?? 'this tenant'} yet. Ask an admin to invite you, then sign in again.`

    return (
      <div className="flex items-center justify-center h-screen bg-background p-6">
        <div className="max-w-md w-full bg-surface border border-border rounded-2xl p-8 text-center shadow-sm">
          <h1 className="font-semibold mb-2">{title}</h1>
          <p className="text-sm text-muted-foreground mb-4">{body}</p>
          {error && <p className="text-xs text-destructive mb-4 break-words">{error}</p>}
          <button
            onClick={() => signOut()}
            className="px-4 py-2 text-sm bg-accent text-accent-foreground rounded-lg hover:opacity-90"
          >
            Sign out
          </button>
        </div>
      </div>
    )
  }

  // 'no_workspace' and 'ready' fall through to the app shell.
  // The workspace empty state is handled inside the shell by NoWorkspaceBanner.
  return <Outlet />
}
